    "code": "<?php\nif (session_status() === PHP_SESSION_NONE) {\n    $is_https = (\n        (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ||\n        (isset($_SERVER['SERVER_PORT']) && (int)$_SERVER['SERVER_PORT'] === 443) ||\n        (isset($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https')\n    );\n    ini_set('session.use_strict_mode', 1);\n    ini_set('session.cookie_httponly', 1);\n    ini_set('session.use_only_cookies', 1);\n    ini_set('session.cookie_samesite', 'Lax');\n    if ($is_https) {\n        ini_set('session.cookie_secure', 1);\n    }\n    session_start();\n}\n\nfunction generate_csrf_token(): string {\n    if (empty($_SESSION['csrf_token']) || !is_string($_SESSION['csrf_token']) || strlen($_SESSION['csrf_token']) < 32) {\n        $_SESSION['csrf_token'] = bin2hex(random_bytes(32));\n    }\n    return $_SESSION['csrf_token'];\n}\n\nfunction csrf_field(): string {\n    $token = generate_csrf_token();\n    return '<input type=\"hidden\" name=\"csrf_token\" value=\"' . htmlspecialchars($token, ENT_QUOTES, 'UTF-8') . '\">';\n}\n\nfunction verify_csrf(): void {\n    if ($_SERVER['REQUEST_METHOD'] === 'POST') {\n        // Verifikasi Origin header jika dikirim oleh browser untuk mencegah Cross-Origin POST\n        if (!empty($_SERVER['HTTP_ORIGIN']) && !empty($_SERVER['HTTP_HOST'])) {\n            $origin_host = parse_url((string)$_SERVER['HTTP_ORIGIN'], PHP_URL_HOST);\n            $current_host = explode(':', (string)$_SERVER['HTTP_HOST'])[0];\n            if ($origin_host && $current_host && strcasecmp($origin_host, $current_host) !== 0) {\n                if (!headers_sent()) {\n                    http_response_code(403);\n                }\n                die('Validasi Keamanan Gagal (Cross-Origin Request Ditolak).');\n            }\n        }\n\n        $token = $_POST['csrf_token'] ?? ($_SERVER['HTTP_X_CSRF_TOKEN'] ?? '');\n        $session_token = $_SESSION['csrf_token'] ?? '';\n        if (empty($token) || empty($session_token) || !hash_equals((string)$session_token, (string)$token)) {\n            if (!headers_sent()) {\n                http_response_code(403);\n            }\n            $is_ajax = (\n                (!empty($_SERVER['HTTP_ACCEPT']) && strpos($_SERVER['HTTP_ACCEPT'], 'application/json') !== false) ||\n                (!empty($_SERVER['SCRIPT_NAME']) && strpos($_SERVER['SCRIPT_NAME'], 'api-') !== false) ||\n                (!empty($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest')\n            );\n            if ($is_ajax) {\n                if (!headers_sent()) {\n                    header('Content-Type: application/json; charset=utf-8');\n                }\n                die(json_encode([\n                    'ok' => false,\n                    'error' => 'Validasi Keamanan Gagal (CSRF Token Invalid atau Sesi Kedaluwarsa). Silakan muat ulang halaman.'\n                ]));\n            }\n            die('Validasi Keamanan Gagal (CSRF Token Invalid). Silakan muat ulang halaman dan coba lagi.');\n        }\n    }\n}\n"
